    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 channels,
    .param .s32 height,
    .param .s32 width,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 ksize,
    .param .s32 stride,
    .param .s32 pad,
    .param .s32 dil,
    .param .s32 has_bias,
    .param .s32 tile_w,
    .param .s32 ow_tiles,
    .param .s32 oh_tiles
