    mul.lo.s32 %r55, %r55, %r12;            // (k-1)*d
    add.s32 %r23, %r23, %r55;
    add.s32 %r23, %r23, 1;                  // RH
    add.s32 %r56, %r18, -1;
    mul.lo.s32 %r24, %r56, %r9;
    add.s32 %r24, %r24, 1;                  // CW = (tw-1)*s + 1
