    shl.b64 %rd2, %rd1, 2;
    ld.param.u64 %rd3, [wt_ptr];
    add.s64 %rd4, %rd3, %rd2;
    ld.global.f32 %f1, [%rd4];
    shl.b32 %r31, %r33, 2;
    add.u32 %r32, %r29, %r31;
    st.shared.f32 [%r32], %f1;
    add.s32 %r33, %r33, %r34;
