    div.s32 %r42, %r1, %r18;                // ty
    div.u32 %r53, %r34, %r18;               // nty = ntid / tw
    add.s32 %r43, %r19, %r41;               // ow
    setp.ge.s32 %p8, %r43, %r15;
    @%p8 bra DONE;
    mul.lo.s32 %r44, %r41, %r9;             // iw_local = tx*s
    mov.s32 %r45, %r42;                     // rr = ty
