    mul.lo.s32 %r50, %r49, %r24;            // row*CW
    add.s32 %r50, %r50, %r44;               // + iw_local
    shl.b32 %r50, %r50, 2;
    add.u32 %r50, %r50, %r27;
    ld.shared.f32 %f4, [%r50];
