            oh_tiles = (oh + 63) // 64
            module.launch(
                "depthwise_conv2d_kx1",
                grid=(ow_tiles * oh_tiles * n * c, 1, 1),
                block=(512, 1, 1),
                arguments=[
                    x,
                    self.conv2d.weight,
                    bias_tensor,
                    out,
                    i32(c),
                    i32(h),
                    i32(w),
                    i32(oh),
                    i32(ow),
                    i32(k),
                    i32(s),
                    i32(p),
                    i32(d),
                    i32(has_bias),
                    i32(tw),
                    i32(ow_tiles),
                    i32(oh_tiles),
                ],
                shared_memory=smem,
                stream=torch.cuda.current_stream(x.device),
            )
        return out

